HELLO: PROCEDURE OPTIONS(MAIN);
    PUT LIST('Hello, World!');
END HELLO;

program Hello;
begin
  writeln('Hello, World!');
end.

MODULE Hello;
FROM InOut IMPORT WriteString, WriteLn;
BEGIN
  WriteString("Hello, World!");
  WriteLn
END Hello.

with Ada.Text_IO;
procedure Hello is
begin
   Ada.Text_IO.Put_Line("Hello, World!");
end Hello;

module hello;
  initial begin
    $display("Hello, World!");
    $finish;
  end
endmodule

MODULE Hello;
IMPORT Out;
BEGIN
  Out.String("Hello, World!");
  Out.Ln
END Hello.

